import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Frame-Panels stylen (experimentell)","description":"UIX-Styling innerhalb unterstützter App- und Custom-Panel-Frames aktivieren.","frontmatter":{"title":"Frame-Panels stylen (experimentell)","description":"UIX-Styling innerhalb unterstützter App- und Custom-Panel-Frames aktivieren."},"headers":[],"relativePath":"projects/uix/extras/style-frame-panels.md","filePath":"projects/uix/extras/style-frame-panels.md","lastUpdated":1793126212000}'),a={name:"projects/uix/extras/style-frame-panels.md"};function s(l,e,o,d,m,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="frame-panels-stylen-experimentell" tabindex="-1">Frame-Panels stylen (experimentell) <a class="header-anchor" href="#frame-panels-stylen-experimentell" aria-label="Permalink to &quot;Frame-Panels stylen (experimentell)&quot;">​</a></h1><p>Standardmäßig fügt UIX keine Styles in Frame-Inhalte ein. Aktiviere diese experimentelle Einstellung, damit die interne UIX-Laufzeit in unterstützten gleichursprünglichen App- und Custom-Panel-Frames ausgeführt wird. Das Styling des Host-Elements mit <code>uix-app</code> und <code>uix-panel-custom</code> ist von dieser Option nicht betroffen.</p><div class="warning custom-block"><p class="custom-block-title">Kompatibilität mit Frameworks</p><p>Die Frame-Laufzeit wurde ausführlich mit dem Lit-basierten Frontend von Home Assistant getestet. Apps und Custom Panels, die in iframes mit anderen Frameworks laufen, können ein anderes Lebenszyklus- oder Shadow-DOM-Verhalten haben. Panels mit einem üblichen Light-DOM-Root und ohne Shadow-DOM-Grenzen funktionieren in der Regel gut. Panels, die ihr DOM reaktiv verwalten oder komplexes Shadow DOM verwenden, müssen für die jeweilige App geprüft werden. Untersuche den Frame, teste jeden Selektor und melde Kompatibilitätsprobleme.</p><p>Bei Frames ohne Lit verwendet UIX ein Fallback-Stylesheet, statt einen <code>uix-node</code> in das App-DOM einzufügen. Dieses Fallback unterstützt direktes CSS einschließlich Templates, aber keine UIX-YAML-Selektorpfade. Verwende im direkten Style-Block normale CSS-Selektoren.</p></div><h2 id="einstellung-uber-die-integrationsoberflache" tabindex="-1">Einstellung über die Integrationsoberfläche <a class="header-anchor" href="#einstellung-uber-die-integrationsoberflache" aria-label="Permalink to &quot;Einstellung über die Integrationsoberfläche&quot;">​</a></h2><p>Die Option ist standardmäßig <strong>nicht gesetzt</strong>. So aktivierst du sie:</p><ol><li>Öffne in Home Assistant <strong>Einstellungen → Geräte &amp; Dienste → UI eXtension → Konfigurieren</strong>.</li><li>Wähle im Menü <strong>Experimentelle Einstellungen</strong>.</li><li>Aktiviere <strong>Frame-Panels stylen</strong>.</li><li>Speichere die Einstellung.</li></ol><p>Die Einstellung gilt sofort für alle verbundenen Browsersitzungen. Damit sie auf ein gerade angezeigtes Frame-Panel angewendet wird, kann ein Neuladen der Seite erforderlich sein.</p><h2 id="verhalten-bei-aktivierter-option" tabindex="-1">Verhalten bei aktivierter Option <a class="header-anchor" href="#verhalten-bei-aktivierter-option" aria-label="Permalink to &quot;Verhalten bei aktivierter Option&quot;">​</a></h2><p>Wenn die Option aktiviert ist:</p><ul><li>Installiert UIX seine interne, vom Paneltyp unabhängige Laufzeit in unterstützten gleichursprünglichen App- und Custom-Panel-Frames.</li><li>Bei Custom-Panel-Frames verwendet UIX den Namen des Panels als Theme-Ziel. Bei App-Frames wird zuerst der vollständige Add-on-Slug und danach der vom Repository unabhängige Slug geprüft.</li><li>UIX fügt einen Styling-Knoten nur ein, wenn das aktive Theme ein passendes Ziel <code>uix-&lt;target&gt;</code> definiert. Frames ohne passenden Abschnitt <code>uix-&lt;target&gt;</code> bleiben unverändert.</li><li>Wenn UIX erkennt, dass kein Theme angewendet wurde, wird UIX Styling mit dem aktuell geladenen Home-Assistant-Frontend-Theme ausgeführt. Einige Custom Panels wie HACS wenden das Theme selbst an; in diesem Fall übernimmt UIX Styling dieses Theme.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Das Ziel für <code>uix-&lt;target&gt;</code> findest du am einfachsten in der Browser-Entwicklerkonsole. Die von <code>uixFrame.js</code> ausgegebene UIX-Ladeinformation sieht beispielsweise so aus:</p><p><span style="background:#CE3226;color:white;padding:2px 5px;font-weight:bold;border-radius:5px;">💡 UIX 8.4.0 IS INSTALLED 💡 for hacs-frontend</span></p><p>Der letzte Teil der Meldung ist das Ziel, hier also <code>hacs-frontend</code>.</p></div>',11)])])}const g=n(a,[["render",s]]);export{c as __pageData,g as default};
